package android.app;
public class Notification { public int icon,flags,defaults,priority; public long when; public CharSequence tickerText; public android.os.Bundle extras=new android.os.Bundle(); public PendingIntent contentIntent,deleteIntent; public static class Builder { private final Notification n=new Notification(); public Builder(android.content.Context c) {} public Builder(android.content.Context c,String channel) {} public Builder setContentTitle(CharSequence t) { n.extras.putCharSequence("android.title",t); return this; } public Builder setContentText(CharSequence t) { n.extras.putCharSequence("android.text",t); return this; } public Builder setSmallIcon(int i) { n.icon=i; return this; } public Builder setContentIntent(PendingIntent i) { n.contentIntent=i; return this; } public Builder setDeleteIntent(PendingIntent i) { n.deleteIntent=i; return this; } public Builder setAutoCancel(boolean b) { return this; } public Builder setOngoing(boolean b) { return this; } public Builder setWhen(long w) { n.when=w; return this; } public Builder setPriority(int p) { n.priority=p; return this; } public Builder setChannelId(String s) { return this; } public Notification build() { return n; } public Notification getNotification() { return n; } } }
